WITH filtered AS (SELECT *, SUBSTRING(promo_code, 1, 4) AS promo_code_prefix, LAST_DAY(starts_on) AS starts_on_month_end FROM promotions WHERE starts_on <= '2024-09-18') SELECT a.*, pr.id AS promo_id, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct FROM filtered a LEFT JOIN promotions pr ON COALESCE(a.channel, 'store') = pr.channel AND a.ends_on >= pr.starts_on AND a.ends_on < pr.ends_on + INTERVAL 30 DAYS;
